script:
import { readFileSync, writeFileSync } from 'node:fs';

const input = 'sales.csv';
const currency = 'CNY';
const reportLabel = '春季观察';
const reportTitle = '双月汇总';
const multiplier = 2;
const expectedBiMonthlyTotal = 720;
const expectedCheckCode = 735;

function parseCsv(text) {
  const lines = text.trim().split(/\r?\n/);
  const headers = lines.shift().split(',');
  return lines.map((line) => {
    const cols = line.split(',');
    return Object.fromEntries(headers.map((h, i) => [h, cols[i]]));
  });
}

function formatNumber(n) {
  return Number.isInteger(n) ? String(n) : n.toFixed(2);
}

const rows = parseCsv(readFileSync(input, 'utf8'));
const monthly = new Map();
for (const row of rows) {
  const month = row.date.slice(0, 7);
  const raw = Number(row.amount);
  if (!Number.isFinite(raw)) throw new Error(`Invalid amount: ${row.amount}`);
  monthly.set(month, (monthly.get(month) ?? 0) + raw * multiplier);
}

const summaryRows = [...monthly.entries()]
  .sort(([a], [b]) => a.localeCompare(b))
  .map(([month, total], index, arr) => {
    const prev = index > 0 ? arr[index - 1][1] : null;
    const mom = prev === null || prev === 0 ? null : (total - prev) / prev;
    return { month, currency, total, mom };
  });

const biMonthlyTotal = summaryRows.reduce((sum, row) => sum + row.total, 0);
const checkCode = biMonthlyTotal + 15;

if (biMonthlyTotal !== expectedBiMonthlyTotal) {
  throw new Error(`双月合计核验失败：expected ${expectedBiMonthlyTotal}, got ${biMonthlyTotal}`);
}
if (checkCode !== expectedCheckCode) {
  throw new Error(`校验码核验失败：expected ${expectedCheckCode}, got ${checkCode}`);
}

const csv = [
  'report_title,report_label,month,currency,total_cny_adjusted_x2,mom',
  ...summaryRows.map((row) => [
    reportTitle,
    reportLabel,
    row.month,
    row.currency,
    formatNumber(row.total),
    row.mom === null ? '' : (row.mom * 100).toFixed(2) + '%',
  ].join(',')),
  `双月合计,${reportLabel},双月,${currency},${formatNumber(biMonthlyTotal)},`,
  `校验码,${reportLabel},校验,${currency},${formatNumber(checkCode)},`,
].join('\n') + '\n';
writeFileSync('monthly_summary.csv', csv, 'utf8');

const table = [
  '| 月份 | 币种 | 金额（已按补充要求 ×2） | 环比（MoM） |',
  '|---|---:|---:|---:|',
  ...summaryRows.map((row) => `| ${row.month} | ${row.currency} | ${formatNumber(row.total)} | ${row.mom === null ? 'N/A' : (row.mom * 100).toFixed(2) + '%'} |`),
].join('\n');

const report = `# ${reportTitle}\n\n报告标签：${reportLabel}\n\n币种：${currency}\n\n## 口径说明\n\n- 数据来源：sales.csv。\n- 已采用中途补充要求：报告标题为「${reportTitle}」；报告标签保留「${reportLabel}」；币种保留 ${currency}。\n- 金额展示及 monthly_summary.csv 中的金额均已在原始 sales.csv 金额基础上乘以 ${multiplier}。\n- 新增核验项：双月合计 ${expectedBiMonthlyTotal}，校验码 ${expectedCheckCode}。\n\n## 月度总额与环比分析\n\n${table}\n\n## 双月与校验项\n\n- 双月合计：${formatNumber(biMonthlyTotal)} ${currency}\n- 校验码：${formatNumber(checkCode)}\n\n## 结论\n\n- 2026-01 调整后总额为 ${formatNumber(summaryRows[0].total)} ${currency}。\n- 2026-02 调整后总额为 ${formatNumber(summaryRows[1].total)} ${currency}，较 2026-01 环比增长 ${((summaryRows[1].mom ?? 0) * 100).toFixed(2)}%。\n- 按新口径核验通过：金额已乘以 2，双月合计为 ${formatNumber(biMonthlyTotal)}，校验码为 ${formatNumber(checkCode)}。\n\n## 数据质量说明\n\n- 输入文件包含 ${rows.length} 行销售记录，字段为 date 与 amount。\n- 当前分析覆盖 ${summaryRows[0].month} 至 ${summaryRows[summaryRows.length - 1].month}。\n`;
writeFileSync('report.md', report, 'utf8');

console.log(JSON.stringify({
  status: 'passed',
  inputRows: rows.length,
  reportTitle,
  reportLabel,
  currency,
  multiplier,
  monthlyTotals: Object.fromEntries(summaryRows.map((r) => [r.month, r.total])),
  biMonthlyTotal,
  checkCode,
  outputs: ['monthly_summary.csv', 'report.md', 'reproduce.mjs'],
}, null, 2));
